{"explanation":"Draw a line through one vertex parallel to the opposite side. Alternate interior angles are equal, so the two angles beside the top vertex match the triangle's two base angles. Together with the top angle, they make a straight line, which is 180°. Drag the vertices to change the triangle. The sum stays 180°.","manimCode":"const A = [-2, -1.5, 0];
const B = [2, -1.5, 0];
const C = [-0.5, 1.5, 0];

const dA = new Dot({ point: [...A], color: RED });
const dB = new Dot({ point: [...B], color: BLUE });
const dC = new Dot({ point: [...C], color: GREEN });

const tri = new Polygon({ vertices: [A, B, C], color: WHITE });
tri.setFill(GRAY, 0.15);

const para = new Polygon({ vertices: [[-6, C[1], 0], [6, C[1], 0]], color: YELLOW });
para.setStrokeWidth(2).setFillOpacity(0);

// angle wedges drawn as small filled polygons
function wedge(P, d1, d2, r, color) {
  const a1 = Math.atan2(d1[1], d1[0]);
  let a2 = Math.atan2(d2[1], d2[0]);
  let diff = a2 - a1;
  while (diff > Math.PI) diff -= 2 * Math.PI;
  while (diff < -Math.PI) diff += 2 * Math.PI;
  const pts = [[P[0], P[1], 0]];
  for (let i = 0; i <= 12; i++) {
    const a = a1 + diff * i / 12;
    pts.push([P[0] + r * Math.cos(a), P[1] + r * Math.sin(a), 0]);
  }
  return pts;
}

const wA = new Polygon({ vertices: wedge(A, [1,0], [1,0], 0.5, RED), color: RED });
const wB = new Polygon({ vertices: wedge(B, [1,0], [1,0], 0.5, BLUE), color: BLUE });
const wC1 = new Polygon({ vertices: wedge(C, [1,0], [1,0], 0.5, RED), color: RED });
const wC2 = new Polygon({ vertices: wedge(C, [1,0], [1,0], 0.5, GREEN), color: GREEN });
const wC3 = new Polygon({ vertices: wedge(C, [1,0], [1,0], 0.5, BLUE), color: BLUE });
[[wA, RED], [wB, BLUE], [wC1, RED], [wC2, GREEN], [wC3, BLUE]].forEach(([w, c]) => w.setFill(c, 0.6));

scene.add(para, tri, wA, wB, wC1, wC2, wC3, dA, dB, dC);

function update() {
  const a = dA.getCenter(), b = dB.getCenter(), c = dC.getCenter();
  tri.setVertices([a, b, c]);
  para.setVertices([[-6, c[1], 0], [6, c[1], 0]]);
  const sub = (p, q) => [p[0] - q[0], p[1] - q[1]];
  const r = 0.5;
  wA.setVertices(wedge(a, sub(b, a), sub(c, a), r, RED));
  wB.setVertices(wedge(b, sub(c, b), sub(a, b), r, BLUE));
  // at C: left ray along parallel line -> CA ; CA -> CB ; CB -> right ray
  wC1.setVertices(wedge(c, [-1, 0], sub(a, c), r, RED));
  wC2.setVertices(wedge(c, sub(a, c), sub(b, c), r, GREEN));
  wC3.setVertices(wedge(c, sub(b, c), [1, 0], r, BLUE));
}
makeDraggable(dA, scene, { onDrag: update });
makeDraggable(dB, scene, { onDrag: update });
makeDraggable(dC, scene, { onDrag: update });
update();

const title = new Text({ text: 'Red + Green + Blue = a straight line = 180°', color: YELLOW, fontSize: 30 });
title.moveTo([0, 3.3, 0]);
scene.add(title);

const note = new Text({ text: 'Parallel lines: alternate angles are equal. Drag the vertices!', color: WHITE, fontSize: 24 });
note.moveTo([0, -3.2, 0]);
scene.add(note);

await scene.wait(999999);"}

